{
  "$schema": "./node_modules/oxlint/configuration_schema.json",
  // Plumbing whose failure channel is public `unknown`.
  "rules": { "effecttsgo/any-unknown-in-error-context": "error" },
  "overrides": [
    {
      "files": [
        "packages/foldkit/src/command/index.ts",
        "packages/foldkit/src/html/index.ts",
        "packages/foldkit/src/runtime/managedResourceFibers.ts",
      ],
      "rules": { "effecttsgo/any-unknown-in-error-context": "off" },
    },
    {
      "files": ["examples/ssr/scripts/serve.ts", "packages/node/src/node.ts"],
      "rules": { "effecttsgo/any-unknown-in-error-context": "off" },
    },
  ],
  "ignorePatterns": ["packages/website/src/snippet/", "**/dist/**"],
}
